"use strict";(globalThis.webpackChunkgrc||=[]).push([[53977],{18504(e){e.exports=JSON.parse('{"citeKey":"sun2008towardsfault","slug":"sun-2008-towards-fault-0769","title":"Towards a Fault-aware Computing Environment","authors":["X.-H. Sun","Z. Lan","Y. Li","H. Jin","Z. Zheng"],"venue":"The High Availability and Performance Computing Workshop (HAPCW)","type":"Workshop","entryType":"inproceedings","date":"March, 2008","year":2008,"era":"iit","month":3,"abstract":"In this paper, we propose and present the design and initial development of the Fault awareness Enabled Computing Environment (FENCE) system for high end computing. FENCE is a comprehensive fault management system in the sense that it consists of both post and runtime analysis, integrates both proactive and reactive mechanisms, and combines both application level and system level fault management. Component-based systems are also developed to support the comprehensive FENCE design. Preliminary implementation results are presented.","hasAbstract":true,"lede":"We propose and present the design and initial development of the Fault awareness Enabled Computing Environment (FENCE) system for high end computing.","links":{"pdf":"https://grc.iit.edu/papers/2008/sun-2008-towards-fault-0769.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":["fence"],"memberAuthors":["sun-xian-he"]}')}}]);